window.NLT = {"duration":300.6,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if there was no light in the universe?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.307},{"text":"there","start":0.563},{"text":"was","start":0.82},{"text":"no","start":1.077},{"text":"light","start":1.333},{"text":"in","start":1.59},{"text":"the","start":1.847},{"text":"universe?","start":2.103}]}]},{"id":"start","n":2,"section":1,"title":false,"first":3.85,"end":18.25,"caps":[{"text":"2:40 PM, on a frozen lake in Norway. Every light in the universe just went out.","show":3.85,"hide":8.8,"words":[{"text":"2:40","start":3.85},{"text":"PM,","start":4.067},{"text":"on","start":4.283},{"text":"a","start":4.5},{"text":"frozen","start":4.716},{"text":"lake","start":4.933},{"text":"in","start":5.149},{"text":"Norway.","start":5.366},{"text":"Every","start":5.583},{"text":"light","start":5.799},{"text":"in","start":6.016},{"text":"the","start":6.232},{"text":"universe","start":6.449},{"text":"just","start":6.665},{"text":"went","start":6.882},{"text":"out.","start":7.098}]},{"text":"Not a power cut. The Sun is still in the sky.","show":9.8,"hide":13.05,"words":[{"text":"Not","start":9.8},{"text":"a","start":10.007},{"text":"power","start":10.214},{"text":"cut.","start":10.42},{"text":"The","start":10.627},{"text":"Sun","start":10.834},{"text":"is","start":11.041},{"text":"still","start":11.248},{"text":"in","start":11.455},{"text":"the","start":11.661},{"text":"sky.","start":11.868}]},{"text":"Your eyes are wide open. There's nothing left for them to catch.","show":14.05,"hide":18.25,"words":[{"text":"Your","start":14.05},{"text":"eyes","start":14.295},{"text":"are","start":14.54},{"text":"wide","start":14.785},{"text":"open.","start":15.03},{"text":"There's","start":15.275},{"text":"nothing","start":15.52},{"text":"left","start":15.765},{"text":"for","start":16.01},{"text":"them","start":16.255},{"text":"to","start":16.5},{"text":"catch.","start":16.745}]}]},{"id":"skaters","n":3,"section":1,"title":false,"first":19.05,"end":26.95,"caps":[{"text":"You're doing 24 km/h on two thin blades. So is everyone around you.","show":19.05,"hide":23.4,"words":[{"text":"You're","start":19.05},{"text":"doing","start":19.284},{"text":"24","start":19.518},{"text":"km/h","start":19.753},{"text":"on","start":19.987},{"text":"two","start":20.221},{"text":"thin","start":20.455},{"text":"blades.","start":20.69},{"text":"So","start":20.924},{"text":"is","start":21.158},{"text":"everyone","start":21.392},{"text":"around","start":21.627},{"text":"you.","start":21.861}]},{"text":"And nobody can see.","show":25,"hide":26.95,"words":[{"text":"And","start":25},{"text":"nobody","start":25.341},{"text":"can","start":25.683},{"text":"see.","start":26.024}]}]},{"id":"heat","n":4,"section":1,"title":false,"first":29.35,"end":39.75,"caps":[{"text":"But everything still glows, in a light no eye can see: infrared.","show":29.35,"hide":33.55,"words":[{"text":"But","start":29.35},{"text":"everything","start":29.595},{"text":"still","start":29.84},{"text":"glows,","start":30.085},{"text":"in","start":30.33},{"text":"a","start":30.575},{"text":"light","start":30.82},{"text":"no","start":31.065},{"text":"eye","start":31.31},{"text":"can","start":31.555},{"text":"see:","start":31.8},{"text":"infrared.","start":32.045}]},{"text":"This is what a heat camera would see. Nobody on this lake can see any of it.","show":34.95,"hide":39.75,"words":[{"text":"This","start":34.95},{"text":"is","start":35.148},{"text":"what","start":35.345},{"text":"a","start":35.543},{"text":"heat","start":35.741},{"text":"camera","start":35.938},{"text":"would","start":36.136},{"text":"see.","start":36.334},{"text":"Nobody","start":36.531},{"text":"on","start":36.729},{"text":"this","start":36.926},{"text":"lake","start":37.124},{"text":"can","start":37.322},{"text":"see","start":37.519},{"text":"any","start":37.717},{"text":"of","start":37.915},{"text":"it.","start":38.112}]}]},{"id":"rule","n":5,"section":1,"title":false,"first":40.95,"end":56.45,"caps":[{"text":"Light is one kind of electromagnetism. Take all of it away, and the force that holds your atoms together goes too.","show":40.95,"hide":46.35,"words":[{"text":"Light","start":40.95},{"text":"is","start":41.13},{"text":"one","start":41.31},{"text":"kind","start":41.49},{"text":"of","start":41.67},{"text":"electromagnetism.","start":41.85},{"text":"Take","start":42.03},{"text":"all","start":42.21},{"text":"of","start":42.39},{"text":"it","start":42.57},{"text":"away,","start":42.75},{"text":"and","start":42.93},{"text":"the","start":43.11},{"text":"force","start":43.29},{"text":"that","start":43.47},{"text":"holds","start":43.65},{"text":"your","start":43.83},{"text":"atoms","start":44.01},{"text":"together","start":44.19},{"text":"goes","start":44.37},{"text":"too.","start":44.55}]},{"text":"You wouldn't be in the dark. You'd be dust.","show":47.35,"hide":50.5,"words":[{"text":"You","start":47.35},{"text":"wouldn't","start":47.595},{"text":"be","start":47.84},{"text":"in","start":48.085},{"text":"the","start":48.33},{"text":"dark.","start":48.575},{"text":"You'd","start":48.82},{"text":"be","start":49.065},{"text":"dust.","start":49.31}]},{"text":"So only the light eyes use is gone: 380 to 750 nanometres. Everywhere, at once.","show":51.5,"hide":56.45,"words":[{"text":"So","start":51.5},{"text":"only","start":51.731},{"text":"the","start":51.962},{"text":"light","start":52.193},{"text":"eyes","start":52.424},{"text":"use","start":52.655},{"text":"is","start":52.886},{"text":"gone:","start":53.117},{"text":"380","start":53.348},{"text":"to","start":53.579},{"text":"750","start":53.81},{"text":"nanometres.","start":54.041},{"text":"Everywhere,","start":54.272},{"text":"at","start":54.503},{"text":"once.","start":54.734}]}]},{"id":"body","n":6,"section":1,"title":false,"first":57.85,"end":68.15,"caps":[{"text":"Your skin glows brightest at 9.5 micrometres. 13 times too long for any eye.","show":57.85,"hide":62.65,"words":[{"text":"Your","start":57.85},{"text":"skin","start":58.09},{"text":"glows","start":58.33},{"text":"brightest","start":58.57},{"text":"at","start":58.81},{"text":"9.5","start":59.05},{"text":"micrometres.","start":59.29},{"text":"13","start":59.53},{"text":"times","start":59.77},{"text":"too","start":60.01},{"text":"long","start":60.25},{"text":"for","start":60.49},{"text":"any","start":60.73},{"text":"eye.","start":60.97}]},{"text":"Where your hand touched the ice, the ice is still glowing.","show":64.25,"hide":68.15,"words":[{"text":"Where","start":64.25},{"text":"your","start":64.498},{"text":"hand","start":64.746},{"text":"touched","start":64.995},{"text":"the","start":65.243},{"text":"ice,","start":65.491},{"text":"the","start":65.739},{"text":"ice","start":65.987},{"text":"is","start":66.235},{"text":"still","start":66.484},{"text":"glowing.","start":66.732}]}]},{"id":"count","n":7,"section":1,"title":false,"first":69.55,"end":79.15,"caps":[{"text":"240 people were skating here. Every one of them is out on the ice, in the dark.","show":69.55,"hide":74.5,"words":[{"text":"240","start":69.55},{"text":"people","start":69.754},{"text":"were","start":69.958},{"text":"skating","start":70.161},{"text":"here.","start":70.365},{"text":"Every","start":70.569},{"text":"one","start":70.773},{"text":"of","start":70.977},{"text":"them","start":71.181},{"text":"is","start":71.384},{"text":"out","start":71.588},{"text":"on","start":71.792},{"text":"the","start":71.996},{"text":"ice,","start":72.2},{"text":"in","start":72.404},{"text":"the","start":72.607},{"text":"dark.","start":72.811}]},{"text":"It's −12 °C. Nobody knows which way the shore is.","show":75.7,"hide":79.15,"words":[{"text":"It's","start":75.7},{"text":"−12","start":75.942},{"text":"°C.","start":76.183},{"text":"Nobody","start":76.425},{"text":"knows","start":76.666},{"text":"which","start":76.908},{"text":"way","start":77.149},{"text":"the","start":77.391},{"text":"shore","start":77.632},{"text":"is.","start":77.874}]}]},{"id":"grab","n":8,"section":1,"title":false,"first":81.75,"end":89.7,"caps":[{"text":"Someone just grabbed your arm.","show":81.75,"hide":84.25,"words":[{"text":"Someone","start":81.75},{"text":"just","start":82.1},{"text":"grabbed","start":82.45},{"text":"your","start":82.8},{"text":"arm.","start":83.15}]},{"text":"She was skating behind you. She can't see you either.","show":86.05,"hide":89.7,"words":[{"text":"She","start":86.05},{"text":"was","start":86.306},{"text":"skating","start":86.561},{"text":"behind","start":86.816},{"text":"you.","start":87.072},{"text":"She","start":87.328},{"text":"can't","start":87.583},{"text":"see","start":87.839},{"text":"you","start":88.094},{"text":"either.","start":88.349}]}]},{"id":"help","n":9,"section":1,"title":false,"first":91.1,"end":100.4,"caps":[{"text":"You could still dial 112 by feel. So is everyone else in Norway.","show":91.1,"hide":95.3,"words":[{"text":"You","start":91.1},{"text":"could","start":91.326},{"text":"still","start":91.552},{"text":"dial","start":91.778},{"text":"112","start":92.005},{"text":"by","start":92.231},{"text":"feel.","start":92.457},{"text":"So","start":92.683},{"text":"is","start":92.909},{"text":"everyone","start":93.135},{"text":"else","start":93.362},{"text":"in","start":93.588},{"text":"Norway.","start":93.814}]},{"text":"Every ambulance driver is blind too. Nobody is coming.","show":96.7,"hide":100.4,"words":[{"text":"Every","start":96.7},{"text":"ambulance","start":96.988},{"text":"driver","start":97.276},{"text":"is","start":97.563},{"text":"blind","start":97.851},{"text":"too.","start":98.139},{"text":"Nobody","start":98.427},{"text":"is","start":98.714},{"text":"coming.","start":99.002}]}]},{"id":"sun","n":10,"section":1,"title":false,"first":102,"end":117.15,"caps":[{"text":"The Sun is 2.5° above the hills. You can still feel it on your face.","show":102,"hide":106.4,"words":[{"text":"The","start":102},{"text":"Sun","start":102.205},{"text":"is","start":102.411},{"text":"2.5°","start":102.616},{"text":"above","start":102.821},{"text":"the","start":103.027},{"text":"hills.","start":103.232},{"text":"You","start":103.437},{"text":"can","start":103.643},{"text":"still","start":103.848},{"text":"feel","start":104.053},{"text":"it","start":104.259},{"text":"on","start":104.464},{"text":"your","start":104.669},{"text":"face.","start":104.875}]},{"text":"More than half of its energy still gets here, as infrared. Only the part you could see is gone.","show":107.6,"hide":113,"words":[{"text":"More","start":107.6},{"text":"than","start":107.799},{"text":"half","start":107.998},{"text":"of","start":108.197},{"text":"its","start":108.396},{"text":"energy","start":108.595},{"text":"still","start":108.794},{"text":"gets","start":108.993},{"text":"here,","start":109.192},{"text":"as","start":109.391},{"text":"infrared.","start":109.589},{"text":"Only","start":109.788},{"text":"the","start":109.987},{"text":"part","start":110.186},{"text":"you","start":110.385},{"text":"could","start":110.584},{"text":"see","start":110.783},{"text":"is","start":110.982},{"text":"gone.","start":111.181}]},{"text":"It sets at 3:26 PM. Nobody will see it.","show":114.2,"hide":117.15,"words":[{"text":"It","start":114.2},{"text":"sets","start":114.429},{"text":"at","start":114.659},{"text":"3:26","start":114.888},{"text":"PM.","start":115.118},{"text":"Nobody","start":115.347},{"text":"will","start":115.577},{"text":"see","start":115.806},{"text":"it.","start":116.036}]}]},{"id":"fire","n":11,"section":1,"title":false,"first":118.75,"end":135.6,"caps":[{"text":"The bonfire by the kiosk is still burning at 800 °C. It makes no light at all.","show":118.75,"hide":123.65,"words":[{"text":"The","start":118.75},{"text":"bonfire","start":118.952},{"text":"by","start":119.154},{"text":"the","start":119.355},{"text":"kiosk","start":119.557},{"text":"is","start":119.759},{"text":"still","start":119.961},{"text":"burning","start":120.162},{"text":"at","start":120.364},{"text":"800","start":120.566},{"text":"°C.","start":120.768},{"text":"It","start":120.969},{"text":"makes","start":121.171},{"text":"no","start":121.373},{"text":"light","start":121.575},{"text":"at","start":121.776},{"text":"all.","start":121.978}]},{"text":"A man is walking straight towards it.","show":125.05,"hide":127.9,"words":[{"text":"A","start":125.05},{"text":"man","start":125.335},{"text":"is","start":125.62},{"text":"walking","start":125.905},{"text":"straight","start":126.19},{"text":"towards","start":126.475},{"text":"it.","start":126.76}]},{"text":"He feels it a metre away, and stops. Fire you can't see is still fire.","show":131.1,"hide":135.6,"words":[{"text":"He","start":131.1},{"text":"feels","start":131.31},{"text":"it","start":131.52},{"text":"a","start":131.73},{"text":"metre","start":131.94},{"text":"away,","start":132.15},{"text":"and","start":132.36},{"text":"stops.","start":132.57},{"text":"Fire","start":132.78},{"text":"you","start":132.99},{"text":"can't","start":133.2},{"text":"see","start":133.41},{"text":"is","start":133.62},{"text":"still","start":133.83},{"text":"fire.","start":134.04}]}]},{"id":"town","n":12,"section":1,"title":false,"first":137,"end":146.7,"caps":[{"text":"Every lamp in town is still switched on. All they make now is heat.","show":137,"hide":141.35,"words":[{"text":"Every","start":137},{"text":"lamp","start":137.218},{"text":"in","start":137.435},{"text":"town","start":137.653},{"text":"is","start":137.87},{"text":"still","start":138.088},{"text":"switched","start":138.305},{"text":"on.","start":138.523},{"text":"All","start":138.74},{"text":"they","start":138.958},{"text":"make","start":139.175},{"text":"now","start":139.393},{"text":"is","start":139.61},{"text":"heat.","start":139.828}]},{"text":"Every screen is still on too. Nobody can read a single one.","show":142.75,"hide":146.7,"words":[{"text":"Every","start":142.75},{"text":"screen","start":142.98},{"text":"is","start":143.211},{"text":"still","start":143.441},{"text":"on","start":143.672},{"text":"too.","start":143.902},{"text":"Nobody","start":144.133},{"text":"can","start":144.363},{"text":"read","start":144.593},{"text":"a","start":144.824},{"text":"single","start":145.054},{"text":"one.","start":145.285}]}]},{"id":"road","n":13,"section":2,"title":false,"first":148.1,"end":164.05,"caps":[{"text":"On the road, every driver went blind at the same moment. Most of them stopped.","show":148.1,"hide":153,"words":[{"text":"On","start":148.1},{"text":"the","start":148.329},{"text":"road,","start":148.557},{"text":"every","start":148.786},{"text":"driver","start":149.015},{"text":"went","start":149.243},{"text":"blind","start":149.472},{"text":"at","start":149.701},{"text":"the","start":149.929},{"text":"same","start":150.158},{"text":"moment.","start":150.387},{"text":"Most","start":150.615},{"text":"of","start":150.844},{"text":"them","start":151.073},{"text":"stopped.","start":151.301}]},{"text":"One of them is trying to keep going, by feel.","show":154.6,"hide":157.85,"words":[{"text":"One","start":154.6},{"text":"of","start":154.828},{"text":"them","start":155.055},{"text":"is","start":155.283},{"text":"trying","start":155.51},{"text":"to","start":155.737},{"text":"keep","start":155.965},{"text":"going,","start":156.193},{"text":"by","start":156.42},{"text":"feel.","start":156.648}]},{"text":"Sound takes 1.5 seconds to cross the ice to you.","show":160.65,"hide":164.05,"words":[{"text":"Sound","start":160.65},{"text":"takes","start":160.888},{"text":"1.5","start":161.126},{"text":"seconds","start":161.364},{"text":"to","start":161.602},{"text":"cross","start":161.84},{"text":"the","start":162.078},{"text":"ice","start":162.316},{"text":"to","start":162.554},{"text":"you.","start":162.792}]}]},{"id":"slide","n":14,"section":2,"title":false,"first":165.25,"end":174.15,"caps":[{"text":"The car it hit went through the railing.","show":165.25,"hide":168.25,"words":[{"text":"The","start":165.25},{"text":"car","start":165.513},{"text":"it","start":165.775},{"text":"hit","start":166.038},{"text":"went","start":166.3},{"text":"through","start":166.563},{"text":"the","start":166.825},{"text":"railing.","start":167.088}]},{"text":"It's out on the lake now. Its engine is still running.","show":170.45,"hide":174.15,"words":[{"text":"It's","start":170.45},{"text":"out","start":170.685},{"text":"on","start":170.921},{"text":"the","start":171.156},{"text":"lake","start":171.392},{"text":"now.","start":171.627},{"text":"Its","start":171.863},{"text":"engine","start":172.098},{"text":"is","start":172.334},{"text":"still","start":172.569},{"text":"running.","start":172.805}]}]},{"id":"ice","n":15,"section":2,"title":false,"first":175.35,"end":189,"caps":[{"text":"Clear ice 5 cm thick can hold a person. A car needs about 20.","show":175.35,"hide":179.4,"words":[{"text":"Clear","start":175.35},{"text":"ice","start":175.552},{"text":"5","start":175.755},{"text":"cm","start":175.957},{"text":"thick","start":176.16},{"text":"can","start":176.362},{"text":"hold","start":176.565},{"text":"a","start":176.767},{"text":"person.","start":176.97},{"text":"A","start":177.172},{"text":"car","start":177.375},{"text":"needs","start":177.578},{"text":"about","start":177.78},{"text":"20.","start":177.983}]},{"text":"Where the stream comes in, the ice is only 8.","show":180.8,"hide":184.05,"words":[{"text":"Where","start":180.8},{"text":"the","start":181.028},{"text":"stream","start":181.255},{"text":"comes","start":181.483},{"text":"in,","start":181.71},{"text":"the","start":181.938},{"text":"ice","start":182.165},{"text":"is","start":182.393},{"text":"only","start":182.62},{"text":"8.","start":182.848}]},{"text":"It's going through.","show":187.05,"hide":189,"words":[{"text":"It's","start":187.05},{"text":"going","start":187.505},{"text":"through.","start":187.96}]}]},{"id":"steam","n":16,"section":2,"title":false,"first":191,"end":201.75,"caps":[{"text":"Lake water under ice is at 0 °C. That's 12 degrees warmer than the air.","show":191,"hide":195.55,"words":[{"text":"Lake","start":191},{"text":"water","start":191.212},{"text":"under","start":191.425},{"text":"ice","start":191.637},{"text":"is","start":191.849},{"text":"at","start":192.062},{"text":"0","start":192.274},{"text":"°C.","start":192.486},{"text":"That's","start":192.699},{"text":"12","start":192.911},{"text":"degrees","start":193.123},{"text":"warmer","start":193.336},{"text":"than","start":193.548},{"text":"the","start":193.76},{"text":"air.","start":193.973}]},{"text":"To a heat camera, the hole glows. To everyone out here, it is invisible.","show":197.15,"hide":201.75,"words":[{"text":"To","start":197.15},{"text":"a","start":197.38},{"text":"heat","start":197.61},{"text":"camera,","start":197.84},{"text":"the","start":198.07},{"text":"hole","start":198.3},{"text":"glows.","start":198.53},{"text":"To","start":198.76},{"text":"everyone","start":198.99},{"text":"out","start":199.22},{"text":"here,","start":199.45},{"text":"it","start":199.68},{"text":"is","start":199.91},{"text":"invisible.","start":200.14}]}]},{"id":"world","n":17,"section":2,"title":false,"first":203.55,"end":216.95,"caps":[{"text":"Right now, 8 billion people are blind.","show":203.55,"hide":206.45,"words":[{"text":"Right","start":203.55},{"text":"now,","start":203.84},{"text":"8","start":204.13},{"text":"billion","start":204.42},{"text":"people","start":204.71},{"text":"are","start":205},{"text":"blind.","start":205.29}]},{"text":"Every plant on Earth just stopped making food. They live on exactly this light.","show":207.65,"hide":212.6,"words":[{"text":"Every","start":207.65},{"text":"plant","start":207.898},{"text":"on","start":208.145},{"text":"Earth","start":208.393},{"text":"just","start":208.64},{"text":"stopped","start":208.888},{"text":"making","start":209.135},{"text":"food.","start":209.383},{"text":"They","start":209.63},{"text":"live","start":209.878},{"text":"on","start":210.125},{"text":"exactly","start":210.373},{"text":"this","start":210.62},{"text":"light.","start":210.868}]},{"text":"And every plane in the sky is still flying.","show":213.8,"hide":216.95,"words":[{"text":"And","start":213.8},{"text":"every","start":214.045},{"text":"plane","start":214.29},{"text":"in","start":214.535},{"text":"the","start":214.78},{"text":"sky","start":215.025},{"text":"is","start":215.27},{"text":"still","start":215.515},{"text":"flying.","start":215.76}]}]},{"id":"plane","n":18,"section":2,"title":false,"first":218.35,"end":227.1,"caps":[{"text":"This one is 12 km from its runway, 630 metres up.","show":218.35,"hide":221.8,"words":[{"text":"This","start":218.35},{"text":"one","start":218.57},{"text":"is","start":218.789},{"text":"12","start":219.009},{"text":"km","start":219.228},{"text":"from","start":219.448},{"text":"its","start":219.667},{"text":"runway,","start":219.887},{"text":"630","start":220.106},{"text":"metres","start":220.326},{"text":"up.","start":220.545}]},{"text":"Its pilots can't read a single instrument.","show":224,"hide":227.1,"words":[{"text":"Its","start":224},{"text":"pilots","start":224.31},{"text":"can't","start":224.62},{"text":"read","start":224.93},{"text":"a","start":225.24},{"text":"single","start":225.55},{"text":"instrument.","start":225.86}]}]},{"id":"sing","n":19,"section":2,"title":false,"first":228.7,"end":238,"caps":[{"text":"Lake ice cracks as it cools, and the sound runs through it for kilometres.","show":228.7,"hide":233.4,"words":[{"text":"Lake","start":228.7},{"text":"ice","start":228.935},{"text":"cracks","start":229.17},{"text":"as","start":229.405},{"text":"it","start":229.64},{"text":"cools,","start":229.875},{"text":"and","start":230.11},{"text":"the","start":230.345},{"text":"sound","start":230.58},{"text":"runs","start":230.815},{"text":"through","start":231.05},{"text":"it","start":231.285},{"text":"for","start":231.52},{"text":"kilometres.","start":231.755}]},{"text":"In the dark, it's the only map you have.","show":235,"hide":238,"words":[{"text":"In","start":235},{"text":"the","start":235.233},{"text":"dark,","start":235.467},{"text":"it's","start":235.7},{"text":"the","start":235.933},{"text":"only","start":236.167},{"text":"map","start":236.4},{"text":"you","start":236.633},{"text":"have.","start":236.867}]}]},{"id":"water","n":20,"section":3,"title":false,"first":240.4,"end":255.7,"caps":[{"text":"Someone is in the water.","show":240.4,"hide":242.6,"words":[{"text":"Someone","start":240.4},{"text":"is","start":240.708},{"text":"in","start":241.016},{"text":"the","start":241.324},{"text":"water.","start":241.632}]},{"text":"The driver got out of the car. He's holding on to the edge of the ice.","show":244.4,"hide":248.9,"words":[{"text":"The","start":244.4},{"text":"driver","start":244.597},{"text":"got","start":244.794},{"text":"out","start":244.991},{"text":"of","start":245.188},{"text":"the","start":245.384},{"text":"car.","start":245.581},{"text":"He's","start":245.778},{"text":"holding","start":245.975},{"text":"on","start":246.172},{"text":"to","start":246.369},{"text":"the","start":246.566},{"text":"edge","start":246.763},{"text":"of","start":246.959},{"text":"the","start":247.156},{"text":"ice.","start":247.353}]},{"text":"In water at 0 °C, you have 1 minute to get your breath back. About 10 before your arms stop working.","show":250.3,"hide":255.7,"words":[{"text":"In","start":250.3},{"text":"water","start":250.48},{"text":"at","start":250.66},{"text":"0","start":250.84},{"text":"°C,","start":251.02},{"text":"you","start":251.2},{"text":"have","start":251.38},{"text":"1","start":251.56},{"text":"minute","start":251.74},{"text":"to","start":251.92},{"text":"get","start":252.1},{"text":"your","start":252.28},{"text":"breath","start":252.46},{"text":"back.","start":252.64},{"text":"About","start":252.82},{"text":"10","start":253},{"text":"before","start":253.18},{"text":"your","start":253.36},{"text":"arms","start":253.54},{"text":"stop","start":253.72},{"text":"working.","start":253.9}]}]},{"id":"crawl","n":21,"section":3,"title":false,"first":257.3,"end":272,"caps":[{"text":"Standing, you press on the ice through two blades. Lying flat, through your whole body.","show":257.3,"hide":262.65,"words":[{"text":"Standing,","start":257.3},{"text":"you","start":257.55},{"text":"press","start":257.799},{"text":"on","start":258.049},{"text":"the","start":258.299},{"text":"ice","start":258.548},{"text":"through","start":258.798},{"text":"two","start":259.048},{"text":"blades.","start":259.297},{"text":"Lying","start":259.547},{"text":"flat,","start":259.797},{"text":"through","start":260.046},{"text":"your","start":260.296},{"text":"whole","start":260.546},{"text":"body.","start":260.795}]},{"text":"She's holding your ankles. You crawl towards the sound.","show":264.25,"hide":268,"words":[{"text":"She's","start":264.25},{"text":"holding","start":264.542},{"text":"your","start":264.833},{"text":"ankles.","start":265.125},{"text":"You","start":265.417},{"text":"crawl","start":265.708},{"text":"towards","start":266},{"text":"the","start":266.292},{"text":"sound.","start":266.583}]},{"text":"He's 40 metres away.","show":270,"hide":272,"words":[{"text":"He's","start":270},{"text":"40","start":270.35},{"text":"metres","start":270.7},{"text":"away.","start":271.05}]}]},{"id":"edge","n":22,"section":3,"title":false,"first":273.6,"end":287.05,"caps":[{"text":"The ice cracks under your hands.","show":273.6,"hide":276.2,"words":[{"text":"The","start":273.6},{"text":"ice","start":273.903},{"text":"cracks","start":274.207},{"text":"under","start":274.51},{"text":"your","start":274.813},{"text":"hands.","start":275.117}]},{"text":"Cracking isn't breaking. Not yet.","show":278.2,"hide":280.85,"words":[{"text":"Cracking","start":278.2},{"text":"isn't","start":278.571},{"text":"breaking.","start":278.942},{"text":"Not","start":279.313},{"text":"yet.","start":279.684}]},{"text":"He's been in the water for 6 minutes. You're 3 metres from the edge.","show":282.65,"hide":287.05,"words":[{"text":"He's","start":282.65},{"text":"been","start":282.87},{"text":"in","start":283.09},{"text":"the","start":283.31},{"text":"water","start":283.53},{"text":"for","start":283.75},{"text":"6","start":283.97},{"text":"minutes.","start":284.19},{"text":"You're","start":284.41},{"text":"3","start":284.63},{"text":"metres","start":284.85},{"text":"from","start":285.07},{"text":"the","start":285.29},{"text":"edge.","start":285.51}]}]},{"id":"reach","n":23,"section":3,"title":false,"first":288.65,"end":297.05,"caps":[{"text":"You reach out. Your fingers find his sleeve.","show":288.65,"hide":291.85,"words":[{"text":"You","start":288.65},{"text":"reach","start":288.93},{"text":"out.","start":289.21},{"text":"Your","start":289.49},{"text":"fingers","start":289.77},{"text":"find","start":290.05},{"text":"his","start":290.33},{"text":"sleeve.","start":290.61}]},{"text":"And the ice under your chest starts to bend.","show":293.85,"hide":297.05,"words":[{"text":"And","start":293.85},{"text":"the","start":294.099},{"text":"ice","start":294.348},{"text":"under","start":294.597},{"text":"your","start":294.846},{"text":"chest","start":295.094},{"text":"starts","start":295.343},{"text":"to","start":295.592},{"text":"bend.","start":295.841}]}]},{"id":"question","n":24,"section":3,"title":false,"first":298.65,"end":301,"caps":[{"text":"Would you crawl any closer?","show":298.65,"hide":301,"words":[{"text":"Would","start":298.65},{"text":"you","start":298.979},{"text":"crawl","start":299.308},{"text":"any","start":299.637},{"text":"closer?","start":299.966}]}]}]};
